from pathlib import Path
p=Path('app/src/main/java/com/tufanprintops/uretimperformans/MainActivity.java')
s=p.read_text(encoding='utf-8')

# v1.6.0: Generate the selected report as a real PDF inside the app.
# This intentionally bypasses Android PrintManager/print preview because some OEM
# print services stay forever on "Hazırlanıyor" even after the WebView is ready.
for line,anchor in [
    ('import android.graphics.Picture;','import android.graphics.Color;\n'),
    ('import android.graphics.Canvas;','import android.graphics.Color;\n'),
    ('import android.graphics.pdf.PdfDocument;','import android.graphics.Color;\n'),
]:
    if line not in s:
        if anchor not in s: raise SystemExit('import anchor missing: '+anchor)
        s=s.replace(anchor,anchor+line+'\n',1)

if 'REQ_SAVE_PDF = 2203' not in s:
    anchor='    private static final int REQ_SAVE_FILE = 2202;\n'
    if anchor not in s: raise SystemExit('request-code anchor missing')
    s=s.replace(anchor,anchor+'    private static final int REQ_SAVE_PDF = 2203;\n',1)

field_anchor='    private String pendingSaveMime;\n'
if 'private File pendingPdfFile;' not in s:
    if field_anchor not in s: raise SystemExit('field anchor missing')
    s=s.replace(field_anchor,field_anchor+'    private File pendingPdfFile;\n    private String pendingPdfName;\n',1)

# Replace only the bridge printHtml method generated by v1.5.2.
start=s.find('        @JavascriptInterface\n        public boolean printHtml(String title, String html) {')
if start<0:
    start=s.find('        @JavascriptInterface\n        public void printHtml(String title, String html) {')
if start<0: raise SystemExit('printHtml start not found')
bridge_close=s.find('\n    }\n\n    private String sanitizeFileName',start)
if bridge_close<0: raise SystemExit('AndroidBridge close marker not found')
new_method='''        @JavascriptInterface\n        public boolean printHtml(String title, String html) {\n            final String jobTitle = (title == null || title.trim().isEmpty()) ? "Üretim Performans Raporu" : title.trim();\n            final String safeHtml = (html == null || html.trim().isEmpty()) ? "<html><body><h2>Rapor içeriği boş.</h2></body></html>" : html;\n            runOnUiThread(() -> preparePdfWebView(jobTitle, safeHtml));\n            return true;\n        }\n'''
s=s[:start]+new_method+s[bridge_close:]

helper_marker='    private String sanitizeFileName(String n) {'
if helper_marker not in s: raise SystemExit('sanitize helper marker missing')
helpers='''    private void notifyJs(String js) {\n        if (webView != null) webView.post(() -> webView.evaluateJavascript(js, null));\n    }\n\n    private void cleanupPrintWebView() {\n        if (printWebView != null) {\n            try {\n                if (rootLayout != null) rootLayout.removeView(printWebView);\n                printWebView.stopLoading();\n                printWebView.destroy();\n            } catch (Exception ignored) {}\n            printWebView = null;\n        }\n    }\n\n    private void preparePdfWebView(String jobTitle, String safeHtml) {\n        try {\n            notifyJs("if(window.nativePrintPreparing){nativePrintPreparing();}");\n            cleanupPrintWebView();\n            final WebView pv = new WebView(MainActivity.this);\n            printWebView = pv;\n            pv.setBackgroundColor(Color.WHITE);\n            WebSettings ps = pv.getSettings();\n            ps.setJavaScriptEnabled(false);\n            ps.setDomStorageEnabled(false);\n            ps.setLoadWithOverviewMode(false);\n            ps.setUseWideViewPort(true);\n            ps.setOffscreenPreRaster(true);\n            ps.setDefaultFontSize(16);\n            if (rootLayout == null) throw new IllegalStateException("PDF görünüm kapsayıcısı hazır değil");\n            FrameLayout.LayoutParams lp = new FrameLayout.LayoutParams(\n                    ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.MATCH_PARENT);\n            rootLayout.addView(pv, 0, lp);\n\n            final boolean[] started = {false};\n            final Runnable startPdf = () -> {\n                if (started[0] || printWebView != pv || isFinishing()) return;\n                started[0] = true;\n                // Give charts/fonts a short final layout window after onPageFinished.\n                pv.postDelayed(() -> createPdfFromWebView(jobTitle, pv), 700);\n            };\n            pv.setWebViewClient(new WebViewClient() {\n                @Override public void onPageCommitVisible(WebView view, String url) { view.postDelayed(startPdf, 220); }\n                @Override public void onPageFinished(WebView view, String url) { view.postDelayed(startPdf, 220); }\n            });\n            pv.loadDataWithBaseURL("https://print.local/", safeHtml, "text/html", "UTF-8", null);\n            // OEM fallback: PDF generation does not depend solely on WebView callbacks.\n            pv.postDelayed(startPdf, 3000);\n            pv.postDelayed(() -> {\n                if (!started[0] && printWebView == pv) {\n                    started[0] = true;\n                    notifyJs("if(window.nativePrintFailed){nativePrintFailed('PDF görünümü hazırlanamadı.');}");\n                    cleanupPrintWebView();\n                }\n            }, 7000);\n        } catch (Exception ex) {\n            String msg = ex.getMessage() == null ? ex.toString() : ex.getMessage();\n            notifyJs("if(window.nativePrintFailed){nativePrintFailed(" + jsQuote(msg) + ");}");\n            cleanupPrintWebView();\n        }\n    }\n\n    @SuppressWarnings("deprecation")\n    private void createPdfFromWebView(String jobTitle, WebView pv) {\n        if (printWebView != pv || isFinishing()) return;\n        PdfDocument document = null;\n        try {\n            // capturePicture captures the entire laid-out HTML document rather than only the screen viewport.\n            Picture picture = pv.capturePicture();\n            int sourceWidth = picture == null ? 0 : picture.getWidth();\n            int sourceHeight = picture == null ? 0 : picture.getHeight();\n            if (sourceWidth <= 0 || sourceHeight <= 0) {\n                throw new IllegalStateException("Rapor görünümü PDF için ölçülemedi.");\n            }\n\n            // A4 landscape at 72pt/in. A modest margin keeps tables/charts away from printer edges.\n            final int pageWidth = 842;\n            final int pageHeight = 595;\n            final int marginX = 24;\n            final int marginY = 22;\n            final int printableWidth = pageWidth - (marginX * 2);\n            final int printableHeight = pageHeight - (marginY * 2);\n            final float scale = ((float) printableWidth) / ((float) sourceWidth);\n            final float sourcePerPage = printableHeight / scale;\n            int pageCount = Math.max(1, (int) Math.ceil(sourceHeight / sourcePerPage));\n            // Guard against corrupted/accidentally gigantic HTML creating hundreds of pages.\n            pageCount = Math.min(pageCount, 80);\n\n            document = new PdfDocument();\n            for (int i = 0; i < pageCount; i++) {\n                PdfDocument.PageInfo info = new PdfDocument.PageInfo.Builder(pageWidth, pageHeight, i + 1).create();\n                PdfDocument.Page page = document.startPage(info);\n                Canvas canvas = page.getCanvas();\n                canvas.drawColor(Color.WHITE);\n                int save = canvas.save();\n                canvas.clipRect(marginX, marginY, pageWidth - marginX, pageHeight - marginY);\n                canvas.translate(marginX, marginY);\n                canvas.scale(scale, scale);\n                canvas.translate(0f, -(i * sourcePerPage));\n                picture.draw(canvas);\n                canvas.restoreToCount(save);\n                document.finishPage(page);\n            }\n\n            File out = new File(getCacheDir(), "upm-report-" + System.currentTimeMillis() + ".pdf");\n            try (FileOutputStream fos = new FileOutputStream(out, false)) {\n                document.writeTo(fos);\n                fos.flush();\n                fos.getFD().sync();\n            }\n            document.close();\n            document = null;\n\n            if (!out.exists() || out.length() < 256) {\n                try { out.delete(); } catch (Exception ignored) {}\n                throw new IllegalStateException("PDF dosyası oluşturulamadı.");\n            }\n\n            pendingPdfFile = out;\n            String base = sanitizeFileName(jobTitle);\n            pendingPdfName = base.toLowerCase().endsWith(".pdf") ? base : base + ".pdf";\n            cleanupPrintWebView();\n            notifyJs("if(window.nativePrintStarted){nativePrintStarted();}");\n\n            Intent intent = new Intent(Intent.ACTION_CREATE_DOCUMENT);\n            intent.addCategory(Intent.CATEGORY_OPENABLE);\n            intent.setType("application/pdf");\n            intent.putExtra(Intent.EXTRA_TITLE, pendingPdfName);\n            startActivityForResult(intent, REQ_SAVE_PDF);\n        } catch (Exception ex) {\n            if (document != null) { try { document.close(); } catch (Exception ignored) {} }\n            if (pendingPdfFile != null) { try { pendingPdfFile.delete(); } catch (Exception ignored) {} pendingPdfFile = null; }\n            String msg = ex.getMessage() == null ? ex.toString() : ex.getMessage();\n            notifyJs("if(window.nativePrintFailed){nativePrintFailed(" + jsQuote(msg) + ");}");\n            cleanupPrintWebView();\n        }\n    }\n\n'''
if 'private void preparePdfWebView' not in s:
    s=s.replace(helper_marker,helpers+helper_marker,1)

# Save generated PDF through Android's normal document picker.
activity_marker='''        if (requestCode == REQ_SAVE_FILE) {'''
if 'requestCode == REQ_SAVE_PDF' not in s:
    if activity_marker not in s: raise SystemExit('onActivityResult save-file marker missing')
    pdf_result='''        if (requestCode == REQ_SAVE_PDF) {\n            boolean ok = false;\n            File source = pendingPdfFile;\n            String name = pendingPdfName;\n            if (resultCode == RESULT_OK && data != null && data.getData() != null && source != null && source.exists()) {\n                try (FileInputStream in = new FileInputStream(source); OutputStream out = getContentResolver().openOutputStream(data.getData(), "w")) {\n                    if (out != null) {\n                        byte[] buf = new byte[8192]; int n;\n                        while ((n = in.read(buf)) >= 0) out.write(buf, 0, n);\n                        out.flush(); ok = true;\n                    }\n                } catch (Exception ignored) {}\n            }\n            if (source != null) try { source.delete(); } catch (Exception ignored) {}\n            pendingPdfFile = null; pendingPdfName = null;\n            final boolean savedPdf = ok; final String savedPdfName = name;\n            notifyJs(savedPdf\n                    ? "if(window.nativePdfSaved){nativePdfSaved(" + jsQuote(savedPdfName) + ");}"\n                    : "if(window.nativePdfSaveCancelled){nativePdfSaveCancelled();}");\n            return;\n        }\n'''
    s=s.replace(activity_marker,pdf_result+activity_marker,1)

# Clean up temporary resources if the Activity closes.
destroy_old='''        if (printWebView != null) printWebView.destroy();\n        super.onDestroy();'''
destroy_new='''        cleanupPrintWebView();\n        if (pendingPdfFile != null) { try { pendingPdfFile.delete(); } catch (Exception ignored) {} pendingPdfFile = null; }\n        super.onDestroy();'''
if destroy_old in s:
    s=s.replace(destroy_old,destroy_new,1)
elif 'cleanupPrintWebView();\n        if (pendingPdfFile != null)' not in s:
    raise SystemExit('onDestroy print block missing')

p.write_text(s,encoding='utf-8')
print('patched-main-v160-pdfdocument')
